<script lang="ts">
  import {refreshAll} from '$app/navigation';
  import type {Row} from '#lib/client/types.ts';
  import {displayTimestamp,display} from '#lib/client/api.ts';
  import Icon from './Icon.svelte';
  import Status from './Status.svelte';
  let {declarations=[]}:{declarations?:Row[]}=$props();
  let busy=$state('');let error=$state('');let notice=$state('');
  const kinds:Record<string,string>={quote_acceptance:'Angebotsannahme',design:'Gestaltungsfreigabe',inscription:'Inschriftbestätigung',change_request:'Änderungswunsch',delivery:'Lieferbestätigung',acceptance:'Abnahme',withdrawal:'Widerruf'};
  async function refresh(){if(busy)return;busy='refresh';error='';try{await refreshAll();notice='Der aktuelle Stand Ihrer Nachweise wurde geladen.';}catch{error='Die Nachweise konnten nicht aktualisiert werden. Bitte versuchen Sie es erneut.';}finally{busy='';}}
  async function download(row:Row){if(busy)return;busy=row.id;error='';notice='';try{const response=await fetch(row.download_url||`/api/v1/portal/declarations/${encodeURIComponent(row.id)}/receipt`,{credentials:'same-origin',cache:'no-store'});if(!response.ok){const body=await response.json().catch(()=>null);if(response.status===409){notice='Dieser Nachweis wird noch erstellt. Ihre Erklärung ist bereits gespeichert. Bitte aktualisieren Sie die Nachweise in Kürze erneut.';return;}throw new Error(body?.error?.message||'Der Nachweis ist momentan nicht abrufbar.');}const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download='Schubert-Eingangsnachweis.pdf';link.dataset.sveltekitReload='true';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){error=e instanceof Error?e.message:'Der Nachweis konnte nicht geladen werden.';}finally{busy='';}}
</script>
{#if declarations.length}<section class="panel mt"><header class="panel-header"><div><h2>Ihre Erklärungen & Nachweise</h2><p>Die abgegebenen Erklärungen beziehen sich auf den damals angezeigten Stand.</p></div><button class="btn small" disabled={!!busy} onclick={refresh}><Icon name="refresh" size={15} class={busy==='refresh'?'spin':''}/>Aktualisieren</button></header><div class="panel-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if notice}<div class="notice info" role="status">{notice}</div>{/if}{#each declarations as declaration}<article class="declaration-receipt"><div class="receipt-heading"><div><h3>{kinds[declaration.kind]||'Kundenerklärung'}</h3><p class="small muted mt">{displayTimestamp(declaration.received_at||declaration.created_at)} · {declaration.person_name}</p></div><Status value={declaration.status||'received'}/></div><p class="small mt" style="white-space:pre-wrap">{declaration.statement}</p><div class="mt">{#if declaration.confirmed_snapshot}{@const scope=declaration.confirmed_snapshot}<section class="action-preview"><h3>Bestätigter Auftrag{declaration.order_number?' '+declaration.order_number:''}</h3>{#if scope.selectedOptions?.length}<p class="small mt">Zusätzlich gewählte Positionen: {scope.selectedOptions.join(', ')}</p>{/if}{#if scope.lines?.length}<div class="table-scroll mt receipt-lines"><table class="data-table"><thead><tr><th>Beauftragte Leistung</th><th>Menge / Einheit</th><th class="number">Netto</th></tr></thead><tbody>{#each scope.lines.filter((line:Row)=>line.line_type==='item'&&(!line.optional||line.selected)) as line}<tr><td>{line.description}</td><td>{display(line.quantity,'quantity')} {display(line.unit)}</td><td class="number" data-label="Netto">{display(line.net_amount,'amount')}</td></tr>{/each}</tbody></table></div>{/if}<p class="small mt">Netto {display(scope.net_total,'net_total')} · Umsatzsteuer {display(scope.tax_total,'tax_total')}</p><p class="mt"><strong>{display(scope.gross_total,'gross_amount')} brutto verbindlich beauftragt</strong></p></section>{/if}</div><p class="field-help mt">Eingangsreferenz: {declaration.id}</p>{#if declaration.receipt_document_id}<button class="btn mt" disabled={!!busy} onclick={()=>download(declaration)}><Icon name={busy===declaration.id?'refresh':'download'} size={16} class={busy===declaration.id?'spin':''}/>{busy===declaration.id?'Wird geladen …':'PDF-Eingangsnachweis herunterladen'}</button>{:else}<p class="field-help mt">Der PDF-Nachweis ist noch nicht verfügbar. Über „Aktualisieren“ können Sie den Stand erneut abrufen.</p>{/if}</article>{/each}</div></section>{/if}
<style>.declaration-receipt+.declaration-receipt{margin-top:24px;padding-top:24px;border-top:1px solid var(--line)}.receipt-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.receipt-heading h3{font-size:15px;font-weight:500}@media(max-width:760px){.receipt-heading{flex-direction:column;gap:12px}.declaration-receipt>.btn{width:100%}}</style>
